import{_ as d,o as t,c as o,aS as a}from"./chunks/framework.DsJaIkSj.js";const u=JSON.parse('{"title":"包 exports 与宿主 runtime","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/package-exports-and-runtime.md","filePath":"contracts/package-exports-and-runtime.md","lastUpdated":null}'),c={name:"contracts/package-exports-and-runtime.md"};function r(n,e,i,p,m,l){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="包-exports-与宿主-runtime" tabindex="-1">包 exports 与宿主 runtime <a class="header-anchor" href="#包-exports-与宿主-runtime" aria-label="Permalink to &quot;包 exports 与宿主 runtime&quot;">​</a></h1><p>状态：当前权威（交付与解析治理口径）。具体路径、格式、版本和依赖范围以每个包当前 <code>package.json</code> 与发布产物为准，不在本文件复制版本表。</p><h2 id="入口交付" tabindex="-1">入口交付 <a class="header-anchor" href="#入口交付" aria-label="Permalink to &quot;入口交付&quot;">​</a></h2><ul><li>根入口是包 <code>exports[&quot;.&quot;]</code>（或该包等效入口声明）的正式消费面；子路径只有被 <code>exports</code> 声明且其类型与运行时代码进入发布 <code>files</code> 时，才是可依赖的公共入口。</li><li>根入口与每个已声明子路径都必须在发布后的 npm 包中解析到相应类型和运行时。不同包可采用不同的 ESM/CJS/CSS 形态，例如 <code>@qynpm/admin-framework</code> 有 <code>./actions</code>，<code>@qynpm/admin-theme</code> 导出 CSS 子路径，<code>@qynpm/ui</code> 导出组件子路径。</li><li>不将 <code>src</code>、<code>lib</code>、示例路径、工作区 alias 或未声明文件视为公共入口；兄弟包与消费者只能依赖已经声明的根/子路径。</li></ul><h2 id="宿主与依赖" tabindex="-1">宿主与依赖 <a class="header-anchor" href="#宿主与依赖" aria-label="Permalink to &quot;宿主与依赖&quot;">​</a></h2><p>宿主应用按各包 <code>peerDependencies</code> 提供 Vue、Vue Router、Element Plus 等运行时。当前 metadata 的抽样事实是：</p><table tabindex="0"><thead><tr><th>包</th><th>当前内部 peer/dev 依赖证据</th></tr></thead><tbody><tr><td><code>@qynpm/admin-patterns</code></td><td>peer <code>@qynpm/admin-framework</code>、<code>@qynpm/ui</code>；工作区 dev 依赖同名包。</td></tr><tr><td><code>@qynpm/admin-shell</code></td><td>peer <code>@qynpm/admin-framework</code>、<code>@qynpm/admin-theme</code>、<code>@qynpm/ui</code>；工作区 dev 依赖同名包。</td></tr><tr><td><code>@qynpm/table</code></td><td>peer <code>@qynpm/admin-framework</code>、<code>@qynpm/table-schema</code>、<code>@qynpm/ui</code>；工作区 dev 依赖同名包。</td></tr><tr><td><code>@qynpm/form</code></td><td>peer <code>@qynpm/hooks</code>、<code>@qynpm/ui</code>；工作区 dev 依赖同名包。</td></tr><tr><td><code>@qynpm/product-preview</code></td><td>peer <code>@qynpm/hooks</code>、<code>@qynpm/ui</code>；工作区 dev 依赖同名包。</td></tr></tbody></table><p>这些是当前声明事实，不是“建议依赖”或对所有包的抽象分层。消费者最终解析的版本由自己的 <code>package.json</code> 和 lockfile 决定。</p><h2 id="npm-消费与本地联调" tabindex="-1">npm 消费与本地联调 <a class="header-anchor" href="#npm-消费与本地联调" aria-label="Permalink to &quot;npm 消费与本地联调&quot;">​</a></h2><ul><li>日常消费使用正式 npm 包及其声明的入口、peer 依赖和锁定结果。</li><li>需要本地联调构建产物时，消费者必须显式配置解析到目标包的本地 <code>dist</code>（或该包实际发布目录），并验证运行时与类型都来自该目标；这种配置是联调手段，不是默认发布契约。</li><li>改动 versions、exports、dependencies、lockfile、构建或发布脚本前，先核对目标消费者源码、metadata 和 lockfile，并获得相应授权。</li></ul><p>包定位见 <a href="./../catalog/package-ownership">包职责目录</a>；UI 的 Qy-owned 契约见 <a href="./ui-public-interface">UI 公共 interface</a>。</p>',11)])])}const h=d(c,[["render",r]]);export{u as __pageData,h as default};
